const biz = $input.item.json;
const candidates = $input.all();
const ratio = (biz.recycling_ratio || 30) / 100;

// Calculate weekly posts from cadence
const cadenceMap = { '3x_daily': 21, '2x_daily': 14, 'daily': 7, '5x_week': 5, '3x_week': 3, '2x_week': 2, 'weekly': 1, 'off': 0 };
const cadence = biz.cadence || {};
const weeklyTotal = Object.values(cadence).reduce((s, v) => s + (cadenceMap[v] || 0), 0);
const recycleCount = Math.round(ratio * weeklyTotal / 7); // per day

if (recycleCount === 0 || candidates.length === 0) return [];

// Pick top N candidates
const toRecycle = candidates.slice(0, Math.min(recycleCount, candidates.length));
return toRecycle.map(c => ({ json: { ...c.json, business_id: biz.id, business_voice: biz.brand_voice } }));

