const newBrief = item.content?.[0]?.text || item.brief;

// Trigger content generation workflow with the new brief
// This creates a new content entry that goes through the normal pipeline
return [{ json: {
  business_id: item.business_id,
  brief: newBrief,
  platforms: item.platforms,
  template_id: item.template_id,
  recycled_from: item.id,
  source: 'recycling',
} }];
